bool md_configuration_command(cli_schema::CommandId id) noexcept {
  // The generated command catalog owns workflow classification. This facade
  // must not duplicate a feature list because a missing ID would let that
  // command bypass candidate arbitration in the browser runtime.
  const auto spec =
      std::find_if(cli_schema::commands.begin(), cli_schema::commands.end(),
                   [id](const auto &entry) { return entry.id == id; });
  return spec != cli_schema::commands.end() && spec->configuration_command;
}

bool terminal_global_command(cli_schema::CommandId id) noexcept {
  using enum cli_schema::CommandId;
  switch (id) {
  case switch_engine:
  case help:
  case help_edit:
  case help_global:
  case help_globals:
  case help_special_characters:
  case navigate_back:
  case navigate_back_levels:
  case navigate_closing_brace:
  case navigate_exit:
  case navigate_exit_all:
  case navigate_top:
  case navigate_root:
  case navigate_classic_root:
  case md_quit_config:
  case md_configure_exclusive:
  case md_configure_global:
  case md_configure_private:
  case md_configure_read_only:
  case md_edit_config_exclusive:
  case md_edit_config_global:
  case md_edit_config_private:
  case md_edit_config_read_only:
  case md_compare:
  case md_commit:
  case md_discard:
  case ping:
  case ping_count:
  case ping_size:
  case ping_do_not_fragment:
  case ping_size_do_not_fragment:
  case ping_count_size:
  case ping_count_do_not_fragment:
  case ping_count_size_do_not_fragment:
  case ping_ipv6:
  case ping_ipv6_count:
  case ping_ipv6_size:
  case ping_ipv6_count_size:
    return true;
  default:
    // The MD-CLI configuration modes still permit monitoring and
    // troubleshooting commands. Parse every non-configuration command from
    // the operational root before trying the current configuration context.
    // This keeps `show`, `clear` and `reset` usable below /configure as Nokia
    // documents, while relative configuration leaves still fall through to
    // resolve_session_input(). Full configuration paths are intentionally not
    // classified as global because a same-named child must retain contextual
    // precedence.
    return !md_configuration_command(id);
  }
}

